import java.io.*;
import java.util.*;
import java.math.BigInteger;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static final long BASE = 1_000_000_000L;

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long budget = nextLong();
        long[] a = new long[n], cost = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) cost[i] = nextLong();
        // The answer can exceed 64 bits, so the search range uses BigInteger.
        long minA = Long.MAX_VALUE;
        BigInteger high = null;
        for (int i = 0; i < n; i++) {
            minA = Math.min(minA, a[i]);
            BigInteger cap = BigInteger.valueOf(a[i]).multiply(BigInteger.valueOf(budget / cost[i] + 1));
            if (high == null || cap.compareTo(high) < 0) high = cap;
        }
        BigInteger low = BigInteger.valueOf(minA), big = BigInteger.valueOf(BASE);
        while (low.compareTo(high) < 0) {
            BigInteger target = low.add(high).add(BigInteger.ONE).shiftRight(1);
            // Split target - 1 = hi * BASE + lo so that each division fits in 64 bits.
            BigInteger[] qr = target.subtract(BigInteger.ONE).divideAndRemainder(big);
            long hi = qr[0].longValue(), lo = qr[1].longValue();
            long spent = 0;
            boolean ok = true;
            for (int i = 0; i < n && ok; i++) {
                long q1 = hi / a[i], r1 = hi % a[i];
                // x = (target - 1) / a[i]; x >= 2000 * BASE already exceeds any budget.
                if (q1 >= 2000) {
                    ok = false;
                    break;
                }
                long x = q1 * BASE + (r1 * BASE + lo) / a[i];
                if (x > budget / cost[i]) ok = false;
                else {
                    spent += x * cost[i];
                    if (spent > budget) ok = false;
                }
            }
            if (ok) low = target;
            else high = target.subtract(BigInteger.ONE);
        }
        System.out.println(low);
    }
}

package main

import (
	"fmt"
	"io"
	"math/big"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

const base = 1_000_000_000

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, budget := nextInt(), nextInt()
	a := make([]int, n)
	cost := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	for i := range cost {
		cost[i] = nextInt()
	}
	// The answer can exceed 64 bits, so the search range uses big.Int.
	minA := a[0]
	var high *big.Int
	for i := 0; i < n; i++ {
		minA = min(minA, a[i])
		capacity := new(big.Int).Mul(big.NewInt(int64(a[i])), big.NewInt(int64(budget/cost[i]+1)))
		if high == nil || capacity.Cmp(high) < 0 {
			high = capacity
		}
	}
	low := big.NewInt(int64(minA))
	one, bigBase := big.NewInt(1), big.NewInt(base)
	for low.Cmp(high) < 0 {
		target := new(big.Int).Add(low, high)
		target.Add(target, one).Rsh(target, 1)
		// Split target - 1 = hi * base + lo so that each division fits in 64 bits.
		q, r := new(big.Int).QuoRem(new(big.Int).Sub(target, one), bigBase, new(big.Int))
		hi, lo := int(q.Int64()), int(r.Int64())
		spent, ok := 0, true
		for i := 0; i < n && ok; i++ {
			q1, r1 := hi/a[i], hi%a[i]
			// x = (target - 1) / a[i]; x >= 2000 * base already exceeds any budget.
			if q1 >= 2000 {
				ok = false
				break
			}
			x := q1*base + (r1*base+lo)/a[i]
			if x > budget/cost[i] {
				ok = false
			} else {
				spent += x * cost[i]
				if spent > budget {
					ok = false
				}
			}
		}
		if ok {
			low = target
		} else {
			high = target.Sub(target, one)
		}
	}
	fmt.Println(low.String())
}
